{"path": "cart.go", "content": "package cartsvc

import (
    "encoding/json"
    "fmt"
    "io/ioutil"
    "math"
    "os"
    "github.com/shopspring/decimal"
)

const (
    GST = decimal.NewFromFloat(0.05)
)

const (
    SUMMER25 = "SUMMER25"
    WINTER15 = "WINTER15"
    NO_DISCOUNT = "NO_DISCOUNT"
)

var Discounts = map[string]float64{
    SUMMER25: 0.25,
    WINTER15: 0.15,
}

func loadDiscounts() ([]map[string]interface{}, error) {
    data, err := ioutil.ReadFile("discounts.json")
    if err != nil {
        return nil, err
    }

    var discounts []map[string]interface{}
    err = json.Unmarshal(data, &discounts)
    if err != nil {
        return nil, err
    }

    for _, discount := range discounts {
        code := discount["code"]
        percentage := discount["percentage"]
        Discounts[code] = percentage / 100
    }
    return discounts, nil
}

func (c *Cart) Subtotal() decimal.Decimal {
    var sum decimal.Decimal
    sum = decimal.NewFromFloat(0)

    for _, item := range c.Items {
        itemPrice := decimal.NewFromFloat(item.Price).Mul(decimal.NewFromFloat(float64(item.Quantity)))
        sum = sum.Add(itemPrice)
    }

    return sum
}

func (c *Cart) Total() decimal.Decimal {
    var code string
    var discount decimal.Decimal

    if c.Code != "" {
        code = c.Code
        discount = decimal.NewFromFloat(1).Sub(decimal.NewFromFloat(Discounts[c.Code]))
        return c.Subtotal().Mul(discount).Round(2, decimal.HalfUp)
    }
    code = NO_DISCOUNT
    return c.Subtotal().Round(2, decimal.HalfUp)
}

func (c *Cart) String() string {
    return fmt.Sprintf(`cart: %s, discount code: %s, total: %s`, c.Subtotal().StringFixed(2), code, c.Total().StringFixed(2))
}

func main() {
    err := loadDiscounts()
    if err != nil {
        fmt.Fprintf(os.Stderr, "Error loading discounts: %v\n", err)
        os.Exit(1)
    }

    items := []Item{
        {"t-shirt", 19.99, 1},
        {"t-shirt", 19.99, 1},
        {"t-shirt", 19.99, 1},
    }

    c := Cart{
        Code: SUMMER25,
        Items: items,
    }

    fmt.Printf("cart: %s, discount code: %s, total: %s\n", c.Subtotal().StringFixed(2), c.Code, c.Total().StringFixed(2))

    fmt.Fprintf(os.Stderr, "cart: %s, discount code: %s, total: %s\n", c.Subtotal().StringFixed(2), c.Code, c.Total().StringFixed(2))
}"}
